import json, os, sys
out = {}
for t in sys.argv[1:]:
    p = os.path.join(t, "wcc-probe-%s.txt" % os.getpid())
    try:
        with open(p, "w") as f:
            f.write("x")
        out[t] = "WROTE"
        os.remove(p)
    except OSError as e:
        out[t] = type(e).__name__
print(json.dumps(out))

